// MKT-4: the adoption explorer, the jurisdiction comparer and the services page. Everything is already in the page (generated by
// tools/site/explore.mjs); this only filters, sorts, counts, draws the globe and moves things. No network, and no markup is written by script.
(function () {
  var d = document, still = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  d.documentElement.classList.add('js');
  function $(s, r) { return (r || d).querySelector(s); }
  function $$(s, r) { return Array.prototype.slice.call((r || d).querySelectorAll(s)); }

  // Entrances: each section's parts rise once as it enters (content stays visible without script or under reduced motion).
  var seen = 'IntersectionObserver' in window && !still ? new IntersectionObserver(function (es) {
    es.forEach(function (e) { if (e.isIntersecting) { e.target.classList.add('in'); seen.unobserve(e.target); tick(e.target); } });
  }, { rootMargin: '0px 0px -10% 0px' }) : null;
  $$('main section, main > .wrap').forEach(function (s) { if (seen) { s.classList.add('reveal'); seen.observe(s); } });

  // Counters count up to their value when first seen.
  function count(el, to) {
    var from = +el.textContent || 0; if (still || from === to) { el.textContent = to; return; }
    var t0 = performance.now(), dur = 700;
    (function step(t) { var k = Math.min(1, (t - t0) / dur); k = 1 - Math.pow(1 - k, 3); el.textContent = Math.round(from + (to - from) * k); if (k < 1) requestAnimationFrame(step); })(t0);
  }
  function tick(root) { $$('[data-count]', root).forEach(function (el) { if (!el.dataset.done) { el.dataset.done = 1; el.textContent = 0; count(el, +el.dataset.count); } }); }
  if (!seen) tick(d);

  // ---- the explorer
  var table = $('#cases');
  if (table) {
    var rows = $$('tbody tr', table), total = rows.length, form = $('#filters'), q = $('#q');
    var cv = $('#globe'), geo = JSON.parse((cv && cv.dataset.geo) || '{}'), live = {};
    function apply() {
      var want = {}, text = (q.value || '').trim().toLowerCase(), n = 0, by = {}, cs = {}, ind = 0;
      $$('fieldset[data-dim]', form).forEach(function (f) {
        var on = $$('input:checked', f).map(function (i) { return f.dataset.dim + ':' + i.value; });
        if (on.length) want[f.dataset.dim] = on;
      });
      rows.forEach(function (r) {
        var t = ' ' + r.dataset.f + ' ', ok = (!text || r.dataset.q.indexOf(text) >= 0);
        for (var k in want) if (ok) ok = want[k].some(function (v) { return t.indexOf(' ' + v + ' ') >= 0; });
        r.hidden = !ok;
        if (ok) {
          n++; r.dataset.f.split(' ').forEach(function (v) { by[v] = (by[v] || 0) + 1; });
          r.dataset.c.split(' ').forEach(function (c) { if (c) cs[c] = (cs[c] || 0) + 1; });
          if (t.indexOf(' source:independent ') >= 0) ind++;
        }
      });
      $$('[data-n]').forEach(function (b) { b.textContent = by[b.dataset.n] || 0; });
      $$('[data-bar]').forEach(function (b) { b.style.setProperty('--s', ((by[b.dataset.bar] || 0) / total).toFixed(3)); });
      count($('#k-showing'), n); count($('#k-rows'), n); count($('#k-countries'), Object.keys(cs).length); count($('#k-independent'), ind);
      $('#empty').hidden = n > 0; live = cs;
    }
    try { var qs = new URLSearchParams(location.search).get('q'); if (qs) q.value = qs; } catch (e) {}
    form.addEventListener('change', apply); q.addEventListener('input', apply);
    form.addEventListener('reset', function () { setTimeout(apply, 0); });
    form.addEventListener('submit', function (e) { e.preventDefault(); });

    var MAT = { announced: 0, pilot: 1, live: 2, scaled: 3 }, EFF = { low: 0, medium: 1, high: 2 }, dir = {};
    $$('th button[data-sort]', table).forEach(function (b) {
      b.addEventListener('click', function () {
        var k = b.dataset.sort, s = dir[k] = -(dir[k] || -1), body = table.tBodies[0];
        function v(r) { var x = $('[data-k="' + k + '"]', r).textContent.trim().toLowerCase(); return k === 'year' ? +x || 0 : k === 'maturity' ? MAT[r.dataset.f.match(/maturity:(\w+)/)[1]] : k === 'effort' ? EFF[x] : x; }
        rows.slice().sort(function (a, c) { var x = v(a), y = v(c); return (x > y ? 1 : x < y ? -1 : 0) * s; }).forEach(function (r) { body.appendChild(r); });
        $$('th', table).forEach(function (th) { th.removeAttribute('aria-sort'); });
        b.parentNode.setAttribute('aria-sort', s > 0 ? 'ascending' : 'descending');
      });
    });
    apply();
        globe(cv, geo, function () { return live; });
  }
  var lg = !table && $('#globe');
  if (lg) { var lgeo = JSON.parse(lg.dataset.geo || '{}'), all = {}; Object.keys(lgeo).forEach(function (k) { all[k] = 4; }); globe(lg, lgeo, function () { return all; }); }

  // The globe: a dotted sphere (Fibonacci points) with a mark for each country in the current filter; drag to turn.
  function globe(cv, geo, active) {
    if (!cv || !cv.getContext) return;
    var g = cv.getContext('2d'), N = 900, pts = [], rot = 2.0, tilt = 0.32, drag = null, vis = true, css, ink, acc;
    for (var i = 0; i < N; i++) { var y = 1 - (2 * i + 1) / N, r = Math.sqrt(1 - y * y), a = i * 2.39996; pts.push([Math.asin(y), Math.atan2(Math.sin(a) * r, Math.cos(a) * r)]); }
    function proj(lat, lon) {
      var cl = Math.cos(lat), x = cl * Math.sin(lon + rot), z0 = cl * Math.cos(lon + rot), y0 = Math.sin(lat);
      return [x, y0 * Math.cos(tilt) - z0 * Math.sin(tilt), y0 * Math.sin(tilt) + z0 * Math.cos(tilt)];
    }
    function draw() {
      css = getComputedStyle(d.documentElement); ink = css.getPropertyValue('--ink').trim() || '#1A1D23'; acc = css.getPropertyValue('--accent-ink').trim() || '#8A6346';
      var w = cv.width, h = cv.height, R = w * 0.44, cx = w / 2, cy = h / 2, on = active();
      g.clearRect(0, 0, w, h); g.fillStyle = ink;
      pts.forEach(function (p) { var q = proj(p[0], p[1]); if (q[2] > 0) { g.globalAlpha = 0.14 + q[2] * 0.5; g.beginPath(); g.arc(cx + q[0] * R, cy - q[1] * R, 1.9, 0, 6.283); g.fill(); } });
      var ST = { 'in force': ink, 'partly in force': acc, 'guidance only': css.getPropertyValue('--accent').trim(), bill: css.getPropertyValue('--muted').trim(), none: css.getPropertyValue('--faint').trim() };
      Object.keys(geo).forEach(function (c) {
        var n = on[c]; if (!n) return; var ll = geo[c], q = proj(ll[0] * Math.PI / 180, ll[1] * Math.PI / 180); if (q[2] <= 0) return;
        g.fillStyle = ll[2] ? ST[ll[2]] || acc : acc;
        g.globalAlpha = 0.45 + q[2] * 0.55; g.beginPath(); g.arc(cx + q[0] * R, cy - q[1] * R, 4 + Math.sqrt(n) * 2.6, 0, 6.283); g.fill();
      });
      g.globalAlpha = 1;
    }
    function loop() { if (!drag && vis && !still) rot += 0.0035; draw(); if (!still) requestAnimationFrame(loop); }
    cv.addEventListener('pointerdown', function (e) { drag = e.clientX; cv.setPointerCapture(e.pointerId); });
    cv.addEventListener('pointermove', function (e) { if (drag !== null) { rot += (e.clientX - drag) * 0.01; drag = e.clientX; if (still) draw(); } });
    cv.addEventListener('pointerup', function () { drag = null; });
    if ('IntersectionObserver' in window) new IntersectionObserver(function (es) { vis = es[0].isIntersecting; }).observe(cv);
    loop(); if (still) { var t = $('#filters'); if (t) t.addEventListener('change', draw); }
  }

  // ---- the jurisdiction comparer: up to three columns at a time
  var cols = $('#jcols');
  if (cols) {
    var picked = ['EU', 'US', 'IN'].filter(function (j) { return $('.jcol[data-j="' + j + '"]', cols); });
    function show() {
      $$('.jcol', cols).forEach(function (c) { c.hidden = picked.indexOf(c.dataset.j) < 0; c.style.order = picked.indexOf(c.dataset.j); });
      $$('.tile').forEach(function (t) { t.setAttribute('aria-pressed', picked.indexOf(t.dataset.j) >= 0 ? 'true' : 'false'); });
      cols.classList.remove('swap'); void cols.offsetWidth; cols.classList.add('swap');
    }
    $$('.tile').forEach(function (t) {
      t.addEventListener('click', function () {
        var j = t.dataset.j, i = picked.indexOf(j);
        if (i >= 0) { if (picked.length > 1) picked.splice(i, 1); } else { picked.push(j); if (picked.length > 3) picked.shift(); }
        show();
      });
    });
    cols.classList.add('picked'); show();
  }

  // SVG motion (the room's pulses) cannot be stopped from CSS; pause it under reduced motion.
  if (still) $$('svg').forEach(function (s) { if (s.pauseAnimations) s.pauseAnimations(); });

  // ---- the services page: the sector picker
  var pick = $('#sector-pick');
  if (pick) {
    function swap() { $$('.pk').forEach(function (p) { if (p.dataset.g === pick.value) p.removeAttribute('data-off'); else p.setAttribute('data-off', ''); }); }
    pick.addEventListener('change', swap); swap();
  }
})();
